from collections import Counter


def max_occurrences(nums):
    """Write a python function to find the item with maximum occurrences in a given list.

    Returns the most frequent item in ``nums``. If several items share
    the maximum count, the one encountered first is returned. Returns
    ``None`` for an empty list.
    """
    if not nums:
        return None
    return Counter(nums).most_common(1)[0][0]
